CREATE TABLE IF NOT EXISTS panas_accounting_devnet_funding (intent_id uuid PRIMARY KEY, buyer_id uuid NOT NULL REFERENCES panas_accounting_buyers(buyer_id), amount numeric(30,0) NOT NULL CHECK(amount>0 AND amount<=100000000), memo text NOT NULL UNIQUE, treasury_owner text NOT NULL, treasury_token_account text NOT NULL, created_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, signature text UNIQUE, proof jsonb, funded_at timestamptz, CHECK((funded_at IS NULL AND signature IS NULL AND proof IS NULL) OR (funded_at IS NOT NULL AND signature IS NOT NULL AND proof IS NOT NULL)));
ALTER TABLE panas_accounting_devnet_funding ENABLE ROW LEVEL SECURITY;
